import 'package:flutter/widgets.dart';

class AppLocalizations {
  AppLocalizations(this.locale);

  final Locale locale;

  static const Locale fallbackLocale = Locale('en');
  static const List<Locale> supportedLocales = <Locale>[
    Locale('en'),
    Locale('tr'),
    Locale('de'),
    Locale('es'),
    Locale('pt'),
    Locale('it'),
    Locale('fr'),
  ];

  static const LocalizationsDelegate<AppLocalizations> delegate =
      _AppLocalizationsDelegate();

  static AppLocalizations of(BuildContext context) {
    final localizations =
        Localizations.of<AppLocalizations>(context, AppLocalizations);
    return localizations ?? AppLocalizations(fallbackLocale);
  }

  static Locale normalize(Locale locale) {
    for (final supported in supportedLocales) {
      if (supported.languageCode == locale.languageCode) {
        return supported;
      }
    }
    return fallbackLocale;
  }

  String t(String key) {
    final code = _translations.containsKey(locale.languageCode)
        ? locale.languageCode
        : fallbackLocale.languageCode;
    return _translations[code]?[key] ??
        _translations[fallbackLocale.languageCode]?[key] ??
        key;
  }

  /// A language's name in that language.
  ///
  /// The list this fills is read by someone who may not be able to read the
  /// interface they are looking at, so every row carries its own endonym
  /// rather than a name translated into the current language. Those endonyms
  /// are the same string in every block, so one block answers for all.
  ///
  /// This used to be a switch whose `default` returned 'English' -- and the
  /// settings sheet had one of the same shape. On the day Spanish,
  /// Portuguese, Italian and French were added, both would have drawn five
  /// selectable rows all labelled "English", and nothing would have failed:
  /// not the analyzer, not a test, not the build. An unknown code now shows
  /// itself instead of claiming to be a language it is not.
  static String languageName(String code) =>
      _translations[fallbackLocale.languageCode]
          ?['onboarding.lang.name.$code'] ??
      code.toUpperCase();

  /// The key that names a learning-profile language, or null if this app
  /// carries no name for it.
  ///
  /// This mapping was written out four times -- the onboarding native-language
  /// step, the settings sheet, the translation screen's direction labels and
  /// the Today card -- as four switches over the same seven names, each with
  /// its own default. Four copies is four chances to forget one, and adding
  /// Italian to the profile found three of them at once: an Italian learner
  /// was offered "Italian" and shown "English".
  ///
  /// Derived from the key set rather than listed, so a language needs only its
  /// `language.<name>` entry to be named everywhere. Null rather than English
  /// when there is none: a name the app does not have is better shown as the
  /// learner stored it than replaced with a different language.
  static String? languageNameKey(String canonicalName) {
    final key = 'language.${canonicalName.trim().toLowerCase()}';
    final english = _translations[fallbackLocale.languageCode];
    return english != null && english.containsKey(key) ? key : null;
  }

